// tests/unit/test_guide_rules.cpp
#include "../../src/Ai/World/Rpg/Guide/GuideRules.h"
#include "check.h"

#include <sstream>

using namespace Guides;

// The same shape as the converter's output (server/guides/routes/*.tsv), three guides, one bad line of each kind.
static char const* FILE_TEXT =
    "# guide-routes v1 (generated by server/guides/convert.py from Zygor 3.3.5; do not edit)\n"
    "G\ta-human-1-13\talliance\t1\ta-main-guide-13-20\t1\t0\tZygor's Alliance Leveling Guides\\Human (1-13)\n"
    "S\ta-human-1-13\t0\tACCEPT\t783\t0\t823\t0\t0\t-8948.7\t-134.1\t0\t0\t-\t14\t..accept A Threat Within##783\n"
    "S\ta-human-1-13\t1\tOBJECTIVE\t33\t1\t299,300\t0\t0\t-9030.0\t-200.5\t0\t0\t-\t22\t.get 8 Diseased Wolf Pelt|q 33/1\n"
    "S\ta-human-1-13\t2\tACCEPT\t3100\t0\t911\t0\t0\t-8916.0\t-209.0\t0\t0\t1:1,64:1\t35\t..accept Simple Letter##3100\n"
    "S\ta-human-1-13\t3\tGRIND\t0\t0\t-\t0\t-\t-\t-\t0\t2\t-\t29\tding 2\n"
    "S\ta-human-1-13\t5\tGRIND\t0\t0\t-\t0\t-\t-\t-\t0\t3\t-\t30\tding 3\n"
    "S\ta-human-1-13\t4\tWALK\t0\t0\t-\t0\t-\t-\t-\t0\t3\t-\t31\tbad kind\n"
    "S\ta-human-1-13\t4\tRIDE\t0\t0\t-\t0\t0\t-8642.1\t1311.5\t148\t0\t-\t32\t'Ride the boat to Auberdine\n"
    "S\ta-human-1-13\t5\tGOTO\t0\t0\t-\t0\t1\t6400.0\t540.0\t0\t0\t-\t32\t'Ride the boat to Auberdine\n"
    "G\ta-main-guide-13-20\talliance\t13\ta-levels-20-25\t0\t0\tZygor's Alliance Leveling Guides\\Main Guide (13-20)\n"
    "S\ta-main-guide-13-20\t0\tACCEPT\t9\t0\t233\t0\t0\t-10508.0\t1046.0\t0\t0\t-\t4768\t..accept The Killing Fields##9\n"
    "S\ta-human-1-13\t1\tACCEPT\t9\t0\t233\t0\t0\t1\t2\t0\t0\t-\t1\tstep outside its guide\n"
    "G\ta-death-knight-55-60\talliance\t55\t-\t0\t32\tZygor's Alliance Leveling Guides\\Death Knight (55-60)\n"
    "G\ta-levels-20-25\talliance\t20\t-\t0\t0\tZygor's Alliance Leveling Guides\\Levels (20-25)\n"
    "X\tjunk\n";

// GM-BOTAI-0204: the blood elf way out, two hops: the Silvermoon orb (530 -> 0), then the zeppelin (0 -> 1).
static char const* HORDE_TEXT =
    "G\th-blood-elf-1-13\thorde\t1\th-levels-20-25\t512\t0\tZygor's Horde Leveling Guides\\Blood Elf (1-13)\n"
    "S\th-blood-elf-1-13\t0\tGOTO\t0\t0\t-\t0\t530\t9500.0\t-6800.0\t0\t0\t-\t3904\t'Go to Silvermoon City\n"
    "S\th-blood-elf-1-13\t1\tPORTAL\t0\t0\t-\t0\t530\t10034.3\t-7000.4\t1497\t0\t-\t3907\t.' Click the Orb\n"
    "S\th-blood-elf-1-13\t2\tGOTO\t0\t0\t-\t0\t0\t1566.9\t266.9\t0\t0\t-\t3908\t'It will teleport you\n"
    "G\th-undead-1-13\thorde\t1\th-levels-20-25\t16\t0\tZygor's Horde Leveling Guides\\Undead (1-13)\n"
    "S\th-undead-1-13\t0\tRIDE\t0\t0\t-\t0\t0\t2066.1\t285.9\t14\t0\t-\t900\t.' Ride the zeppelin\n"
    "S\th-undead-1-13\t1\tGOTO\t0\t0\t-\t0\t1\t1343.0\t-4648.5\t0\t0\t-\t901\t.' Ride the zeppelin\n"
    "G\th-levels-20-25\thorde\t20\t-\t0\t0\tZygor's Horde Leveling Guides\\Levels (20-25)\n"
    "S\th-levels-20-25\t0\tGOTO\t0\t0\t-\t0\t1\t-400.0\t-2600.0\t0\t0\t-\t5000\t'Go to the Barrens\n";

static GuideFile Load()
{
    std::istringstream in(FILE_TEXT);
    return ParseGuideFile(in);
}

int main()
{
    GuideFile const f = Load();
    CHECK_EQ(4u, f.guides.size());
    CHECK_EQ(4u, f.errors.size());  // seq 5 out of order, WALK, step outside its guide, X
    CHECK_EQ(std::string("line 7: step out of order"), f.errors[0]);
    CHECK_EQ(std::string("line 8: unknown kind WALK"), f.errors[1]);

    Guide const& human = f.guides[0];
    CHECK_EQ(std::string("a-human-1-13"), human.id);
    CHECK_EQ(TEAM_ALLIANCE, human.team);
    CHECK_EQ(std::string("a-main-guide-13-20"), human.next);
    CHECK_EQ(1u, human.raceMask);
    CHECK_EQ(6u, human.steps.size());
    Step const& wolves = human.steps[1];
    CHECK_TRUE(wolves.kind == StepKind::Objective);
    CHECK_EQ(33u, wolves.quest);
    CHECK_EQ(1u, wolves.objective);
    CHECK_EQ(2u, wolves.ids.size());
    CHECK_EQ(300u, wolves.ids[1]);
    CHECK_TRUE(wolves.hasPoint);
    CHECK_EQ(-200.5f, wolves.y);
    CHECK_TRUE(!human.steps[3].hasPoint);
    CHECK_EQ(2u, human.steps[3].level);
    CHECK_EQ(148u, human.steps[4].to);
    CHECK_EQ(std::string(""), f.guides[2].next);
    CHECK_EQ(32u, f.guides[2].classMask);
    CHECK_EQ(std::string("Human (1-13)"), ShortName(human.title));
    CHECK_EQ(std::string("plain"), ShortName("plain"));

    // filters: "Human Warrior, Gnome Warrior"
    Step const& letter = human.steps[2];
    CHECK_TRUE(StepFor(letter, RaceBit(1), ClassBit(1)));
    CHECK_TRUE(StepFor(letter, RaceBit(7), ClassBit(1)));
    CHECK_TRUE(!StepFor(letter, RaceBit(1), ClassBit(8)));  // a human mage
    CHECK_TRUE(StepFor(wolves, RaceBit(4), ClassBit(3)));    // no filter

    // start placement (decision 7)
    std::vector<Guide> const& g = f.guides;
    CHECK_EQ(0, PickStart(g, TEAM_ALLIANCE, RaceBit(1), ClassBit(1), 1));     // a human: its start guide
    CHECK_EQ(-1, PickStart(g, TEAM_ALLIANCE, RaceBit(4), ClassBit(1), 5));    // a dwarf: none in this file
    CHECK_EQ(1, PickStart(g, TEAM_ALLIANCE, RaceBit(4), ClassBit(1), 13));    // main line from 13
    CHECK_EQ(3, PickStart(g, TEAM_ALLIANCE, RaceBit(1), ClassBit(1), 30));    // the highest start at or below
    CHECK_EQ(-1, PickStart(g, TEAM_HORDE, RaceBit(2), ClassBit(1), 30));      // other faction
    CHECK_EQ(-1, PickStart(g, TEAM_ALLIANCE, RaceBit(1), ClassBit(6), 57));   // a death knight below 58
    CHECK_EQ(3, PickStart(g, TEAM_ALLIANCE, RaceBit(1), ClassBit(6), 58));    // never the DK guide itself
    CHECK_EQ(1, GuideIndex(g, "a-main-guide-13-20"));
    CHECK_EQ(-1, GuideIndex(g, "nope"));
    CHECK_TRUE(!Outgrown(&g[1], 14));
    CHECK_TRUE(Outgrown(&g[1], 15));
    CHECK_TRUE(!Outgrown(nullptr, 80));

    // the saved place after the file changed (Review Focus 2)
    CHECK_EQ(2u, RestoreSeq(human, 2, 35));    // unchanged
    CHECK_EQ(1u, RestoreSeq(human, 4, 22));    // steps moved: found by its line
    CHECK_EQ(2u, RestoreSeq(human, 4, 33));    // line gone (its step dropped): the first step after that line
    CHECK_EQ(1u, RestoreSeq(human, 0, 15));
    CHECK_EQ(6u, RestoreSeq(human, 4, 9999));  // past every line: the guide is done
    CHECK_EQ(4u, RestoreSeq(human, 4, 0));     // no line: keep the number
    CHECK_EQ(6u, RestoreSeq(human, 40, 0));    // never past the end
    // the Moonglade detours' quests, both factions (GM-BOTAI-0189, fix round 1): convert.py's DETOUR_QUESTS
    for (uint32_t q : {5923u, 5924u, 5925u, 5926u, 5921u, 5922u, 5929u, 5930u, 5931u, 5932u, 6001u, 6002u, 6121u,
                       6122u, 6123u, 6124u, 6125u, 6126u, 6127u, 6128u, 6129u, 6130u, 26u, 27u, 28u, 29u, 30u, 31u,
                       272u, 5061u})
        CHECK_TRUE(MoongladeQuest(q));
    CHECK_EQ(30u, sizeof(MOONGLADE_QUESTS) / sizeof(MOONGLADE_QUESTS[0]));
    CHECK_TRUE(!MoongladeQuest(5062));
    CHECK_TRUE(!MoongladeQuest(0));
    CHECK_TRUE(RescueHearths(true, 1, 11));
    CHECK_TRUE(RescueHearths(true, 0, 11));    // a druid a first run already cleared (stone on cooldown then)
    CHECK_TRUE(RescueHearths(true, 2, 1));
    CHECK_TRUE(!RescueHearths(true, 0, 1));    // a warrior passing through
    CHECK_TRUE(!RescueHearths(false, 3, 11));  // elsewhere: its quests are dropped, no hearth
    CHECK_EQ(0x00020003u, StepKey(1, 3));
    CHECK_EQ(0x00010000u, StepKey(0, 0));  // never 0

    // crossings: the boat from map 0 to map 1 in the human guide
    Crossing c = FindCrossing(g, TEAM_ALLIANCE, RaceBit(1), 0, 1);
    CHECK_EQ(0, c.guide);
    CHECK_EQ(4u, c.seq);
    CHECK_EQ(0, FindCrossing(g, TEAM_ALLIANCE, RaceBit(4), 0, 1).guide);   // any guide of the faction
    CHECK_EQ(-1, FindCrossing(g, TEAM_ALLIANCE, RaceBit(1), 1, 0).guide);  // no way back in this file
    CHECK_EQ(-1, FindCrossing(g, TEAM_HORDE, RaceBit(2), 0, 1).guide);
    // GM-BOTAI-0204: no direct crossing from map 530 to map 1: the first of two hops (the orb), in its race's guide
    std::istringstream hin(HORDE_TEXT);
    GuideFile const hf = ParseGuideFile(hin);
    CHECK_EQ(0u, hf.errors.size());
    std::vector<Guide> const& h = hf.guides;
    Crossing const orb = FindCrossing(h, TEAM_HORDE, RaceBit(10), 530, 1);
    CHECK_EQ(0, orb.guide);
    CHECK_EQ(1u, orb.seq);
    CHECK_EQ(0, FindCrossing(h, TEAM_HORDE, RaceBit(2), 530, 1).guide);   // an orc there: the same orb
    Crossing const zep = FindCrossing(h, TEAM_HORDE, RaceBit(10), 0, 1);  // a direct one still wins
    CHECK_EQ(1, zep.guide);
    CHECK_EQ(0u, zep.seq);
    CHECK_EQ(0, FindCrossing(h, TEAM_HORDE, RaceBit(10), 530, 0).guide);  // direct: the orb
    CHECK_EQ(-1, FindCrossing(h, TEAM_HORDE, RaceBit(10), 1, 530).guide); // no way back in this file
    CHECK_EQ(-1, FindCrossing(h, TEAM_HORDE, RaceBit(10), 530, 571).guide);  // no second hop to it
    CHECK_EQ(-1, FindCrossing(h, TEAM_ALLIANCE, RaceBit(1), 530, 1).guide);  // other faction
    return UnitFailures();
}
